:root {
  --bg: #07110e;
  --ink: #f4f0e6;
  --muted: #8e9d91;
  --orange: #ff7a1a;
  --orange-2: #ffb347;
  --red: #ff4d3d;
  --cyan: #58e6e0;
  --green: #87e66b;
  --panel: rgba(8, 18, 15, .78);
  --line: rgba(216, 231, 214, .14);
  --font: "Bahnschrift", "DIN Alternate", "Arial Narrow", "Roboto Condensed", system-ui, sans-serif;
  --display: "Haettenschweiler", "Impact", "Arial Narrow Bold", var(--font);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  -webkit-user-select: none;
  user-select: none;
  overscroll-behavior: none;
  touch-action: none;
}

body { position: relative; }

button { font-family: inherit; color: inherit; }

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: none;
  background: #0b1b16;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse at center, transparent 45%, rgba(0, 7, 5, .42) 100%),
    linear-gradient(180deg, rgba(0, 4, 3, .24), transparent 16%, transparent 80%, rgba(0, 4, 3, .32));
}

#scanlines {
  position: fixed;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: .12;
  background: repeating-linear-gradient(0deg, transparent 0, transparent 2px, rgba(0, 0, 0, .22) 3px, transparent 4px);
  mix-blend-mode: multiply;
}

#damageFlash {
  position: fixed;
  inset: 0;
  z-index: 40;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(255, 34, 21, .72));
  transition: opacity .12s ease;
}

#damageFlash.hit { opacity: 1; }
#damageFlash.storm { opacity: .5; animation: stormPulse 1.2s ease-in-out infinite; }
@keyframes stormPulse { 50% { opacity: .16; } }

.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .35s ease, visibility .35s;
}
.screen.active { opacity: 1; visibility: visible; pointer-events: auto; }

/* ============ MENU ============ */
#menu {
  display: flex;
  flex-direction: column;
  padding: clamp(18px, 3vw, 42px) clamp(20px, 4.6vw, 72px) clamp(14px, 2.4vw, 30px);
  background:
    radial-gradient(ellipse at 73% 46%, rgba(255, 110, 25, .14), transparent 34%),
    radial-gradient(ellipse at 20% 90%, rgba(44, 129, 99, .16), transparent 42%),
    linear-gradient(90deg, rgba(4, 11, 9, .94) 0%, rgba(4, 11, 9, .72) 48%, rgba(4, 11, 9, .38) 76%, rgba(4, 11, 9, .7) 100%);
  backdrop-filter: blur(2px);
}
#menu::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(179, 214, 190, .045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(179, 214, 190, .045) 1px, transparent 1px);
  background-size: 78px 78px;
  mask-image: radial-gradient(ellipse at 58% 50%, #000, transparent 75%);
}
#menu::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--orange), transparent);
  opacity: .65;
}

.menu-top {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  color: #0b110c;
  background: linear-gradient(145deg, var(--orange-2), var(--orange) 60%, #e64f08);
  font-family: var(--display);
  font-size: 24px;
  letter-spacing: -.5px;
  transform: skew(-8deg);
  box-shadow: 0 0 22px rgba(255, 112, 24, .28);
}
.brand-copy { display: flex; flex-direction: column; line-height: 1; }
.brand-copy b { font-size: 15px; letter-spacing: .22em; font-weight: 800; }
.brand-copy small { margin-top: 5px; font-size: 8px; letter-spacing: .3em; color: var(--muted); }

.menu-top-actions { display: flex; gap: 8px; }
.icon-btn {
  width: 40px;
  height: 40px;
  border: 1px solid var(--line);
  background: rgba(10, 24, 19, .55);
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: .2s;
}
.icon-btn svg { width: 18px; height: 18px; fill: #b9c8bc; }
.icon-btn:hover { border-color: rgba(255, 138, 43, .7); background: rgba(255, 122, 26, .1); }
.icon-btn:hover svg { fill: var(--orange); }
.icon-btn.muted { opacity: .45; }

.hero {
  position: relative;
  z-index: 2;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(360px, .78fr);
  gap: clamp(24px, 5vw, 90px);
  align-items: center;
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  padding: 2vh 0;
}
.hero-copy { max-width: 710px; animation: rise .7s cubic-bezier(.2, .7, .2, 1) both; }
@keyframes rise { from { opacity: 0; transform: translateY(18px); } }

.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .27em;
  color: #a8b8ab;
  text-transform: uppercase;
}
.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--orange);
  box-shadow: 0 0 0 4px rgba(255, 122, 26, .14), 0 0 12px var(--orange);
  animation: blink 1.8s infinite;
}
@keyframes blink { 50% { opacity: .35; } }
.eyebrow-rule { display: inline-block; width: 34px; height: 1px; background: rgba(255,255,255,.24); }

h1 {
  position: relative;
  margin: 1.6vh 0 1.2vh;
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(88px, 12.4vw, 184px);
  line-height: .72;
  letter-spacing: -.045em;
  text-transform: uppercase;
  color: #f7f2e7;
  text-shadow: 0 8px 0 rgba(0,0,0,.18), 0 18px 42px rgba(0,0,0,.45);
}
h1 em {
  font-style: normal;
  color: transparent;
  background: linear-gradient(180deg, #ffd085 4%, var(--orange) 58%, #e94908 100%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 20px rgba(255, 104, 18, .2));
}
.title-2d {
  position: absolute;
  margin-left: 7px;
  top: 4%;
  display: inline-grid;
  place-items: center;
  padding: 6px 9px 8px;
  font-family: var(--font);
  font-size: clamp(17px, 2.1vw, 30px);
  letter-spacing: .05em;
  color: var(--orange-2);
  border: 2px solid rgba(255, 138, 43, .75);
  background: rgba(13, 22, 17, .65);
  transform: skew(-8deg);
  line-height: 1;
  text-shadow: none;
}

.tagline {
  margin: 2.2vh 0 0;
  font-size: clamp(19px, 2.1vw, 28px);
  font-weight: 300;
  letter-spacing: .015em;
  color: #d8ded4;
}
.tagline strong { color: #fff; font-weight: 700; }
.intro {
  max-width: 490px;
  margin: 1.1vh 0 2.6vh;
  color: #84948a;
  font-size: clamp(12px, 1.1vw, 15px);
  line-height: 1.55;
  letter-spacing: .015em;
}

.deploy-row { display: flex; align-items: stretch; gap: 12px; flex-wrap: wrap; }
.deploy-btn {
  position: relative;
  min-width: 276px;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  border: 0;
  color: #130e07;
  background: linear-gradient(112deg, #ffb14d 0%, var(--orange) 48%, #f1590b 100%);
  cursor: pointer;
  clip-path: polygon(0 0, calc(100% - 15px) 0, 100% 15px, 100% 100%, 0 100%);
  box-shadow: 0 8px 28px rgba(255, 91, 10, .2);
  transition: transform .16s ease, box-shadow .16s ease, filter .16s;
  text-align: left;
}
.deploy-btn::after {
  content: "";
  position: absolute;
  inset: 2px;
  border: 1px solid rgba(255,255,255,.22);
  clip-path: inherit;
  pointer-events: none;
}
.deploy-btn:hover { transform: translateY(-2px); filter: brightness(1.07); box-shadow: 0 12px 38px rgba(255, 91, 10, .34); }
.deploy-btn:active { transform: translateY(0); }
.deploy-icon { display: grid; place-items: center; width: 42px; height: 42px; background: rgba(22, 12, 4, .16); border: 1px solid rgba(35, 17, 3, .18); }
.deploy-icon svg { width: 22px; height: 22px; fill: #241306; }
.deploy-label { display: flex; flex-direction: column; gap: 3px; flex: 1; }
.deploy-label b { font-size: 17px; letter-spacing: .13em; font-weight: 900; }
.deploy-label small { font-size: 8px; letter-spacing: .19em; opacity: .68; font-weight: 700; }
.deploy-arrow { font-size: 23px; font-weight: 300; padding-right: 8px; }

.ghost-btn {
  min-height: 66px;
  padding: 0 23px;
  border: 1px solid rgba(218, 232, 218, .22);
  background: rgba(9, 21, 17, .52);
  color: #c5d1c7;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .19em;
  cursor: pointer;
  transition: .2s;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
}
.ghost-btn:hover { border-color: var(--orange); color: var(--orange-2); background: rgba(255, 122, 26, .08); }
.ghost-btn.wide { width: 100%; min-height: 48px; clip-path: none; margin-top: 8px; }

.quick-stats {
  display: flex;
  gap: clamp(24px, 3.6vw, 52px);
  margin-top: clamp(26px, 4vh, 48px);
  padding-top: 16px;
  border-top: 1px solid rgba(216, 231, 214, .12);
  max-width: 610px;
}
.quick-stats div { display: flex; flex-direction: column; gap: 6px; }
.quick-stats span { font-size: 8px; letter-spacing: .22em; color: #66766c; font-weight: 700; }
.quick-stats b { font-size: 10px; letter-spacing: .13em; color: #c6d2c7; }

.hero-panel {
  position: relative;
  border: 1px solid rgba(202, 225, 205, .13);
  background: linear-gradient(160deg, rgba(17, 34, 27, .55), rgba(5, 13, 11, .7));
  backdrop-filter: blur(8px);
  box-shadow: 0 24px 70px rgba(0, 0, 0, .38);
  animation: rise .8s .12s cubic-bezier(.2, .7, .2, 1) both;
}
.hero-panel::before, .hero-panel::after {
  content: "";
  position: absolute;
  width: 28px;
  height: 28px;
  border-color: var(--orange);
  opacity: .8;
  pointer-events: none;
}
.hero-panel::before { left: -1px; top: -1px; border-left: 2px solid; border-top: 2px solid; }
.hero-panel::after { right: -1px; bottom: -1px; border-right: 2px solid; border-bottom: 2px solid; }
.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px;
  border-bottom: 1px solid rgba(202, 225, 205, .11);
  font-size: 9px;
  letter-spacing: .2em;
  color: #9bad9f;
  font-weight: 700;
}
.status-chip { display: flex; align-items: center; gap: 6px; font-size: 8px; color: #8ee57b; }
.status-chip i { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }

.radar-wrap { position: relative; padding: 1.2vh 5% .6vh; display: grid; place-items: center; }
.radar { width: 100%; max-width: 390px; height: auto; overflow: visible; }
.radar-sweep { transform-origin: 210px 210px; animation: sweep 8s linear infinite; }
@keyframes sweep { to { transform: rotate(360deg); } }
.radar-player { filter: drop-shadow(0 0 8px rgba(255, 138, 43, .9)); }
.ping { animation: ping 2.4s ease-out infinite; transform-box: fill-box; transform-origin: center; }
.ping.p2 { animation-delay: .8s; }
.ping.p3 { animation-delay: 1.5s; }
@keyframes ping { 0% { opacity: 1; transform: scale(.7); } 70%, 100% { opacity: 0; transform: scale(2.3); } }
.radar-label {
  position: absolute;
  font-size: 7px;
  letter-spacing: .18em;
  color: rgba(196, 215, 199, .55);
  font-weight: 700;
}
.radar-label.top { top: 6%; left: 50%; transform: translateX(-50%); }
.radar-label.bottom { bottom: 6%; left: 50%; transform: translateX(-50%); }
.radar-badge {
  position: absolute;
  right: 7%;
  bottom: 13%;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: 7px 9px;
  border-left: 2px solid var(--orange);
  background: rgba(5, 13, 11, .7);
}
.radar-badge span { font-family: var(--display); font-size: 28px; line-height: .9; color: #fff; }
.radar-badge small { font-size: 6px; letter-spacing: .2em; color: #839589; margin-top: 4px; }
.brief-grid { display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid rgba(202, 225, 205, .11); }
.brief-grid div { display: flex; flex-direction: column; gap: 5px; padding: 12px 16px; }
.brief-grid div:nth-child(odd) { border-right: 1px solid rgba(202, 225, 205, .09); }
.brief-grid div:nth-child(-n+2) { border-bottom: 1px solid rgba(202, 225, 205, .09); }
.brief-grid span { font-size: 7px; letter-spacing: .18em; color: #65756a; font-weight: 700; }
.brief-grid b { font-size: 9px; letter-spacing: .13em; color: #c6d2c7; }

.menu-bottom {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  padding-top: 12px;
  border-top: 1px solid rgba(216, 231, 214, .09);
}
.controls-strip { display: flex; gap: clamp(12px, 2vw, 28px); flex-wrap: wrap; }
.controls-strip span { font-size: 8px; letter-spacing: .14em; color: #738279; font-weight: 700; }
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  margin-right: 3px;
  border: 1px solid rgba(211, 229, 213, .28);
  border-bottom-color: rgba(211, 229, 213, .48);
  background: rgba(255,255,255,.055);
  color: #dbe4da;
  font-family: var(--font);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .03em;
  vertical-align: middle;
}
.build-tag { font-size: 7px; letter-spacing: .18em; color: #4e5f54; white-space: nowrap; }
.build-tag span { color: var(--orange); }

/* ============ MODALS ============ */
.modal {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(2, 8, 6, .72);
  backdrop-filter: blur(9px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: .25s;
}
.modal.open { opacity: 1; visibility: visible; pointer-events: auto; }
.modal-card {
  position: relative;
  width: min(760px, 100%);
  max-height: 90vh;
  overflow: auto;
  padding: clamp(24px, 3.4vw, 42px);
  border: 1px solid rgba(209, 231, 211, .18);
  background:
    radial-gradient(ellipse at 90% 0%, rgba(255, 110, 25, .1), transparent 35%),
    linear-gradient(155deg, #10251d, #081410 70%);
  box-shadow: 0 35px 100px rgba(0,0,0,.65);
  clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 20px 100%, 0 calc(100% - 20px));
}
.modal-card::before {
  content: "";
  position: absolute;
  inset: 8px;
  border: 1px solid rgba(209, 231, 211, .06);
  pointer-events: none;
}
.modal-close {
  position: absolute;
  right: 16px;
  top: 12px;
  z-index: 2;
  border: 0;
  background: transparent;
  color: #899b8d;
  font-size: 27px;
  font-weight: 200;
  cursor: pointer;
  line-height: 1;
}
.modal-close:hover { color: var(--orange); }
.modal h2 {
  margin: 8px 0 6px;
  font-family: var(--display);
  font-size: clamp(42px, 6vw, 68px);
  letter-spacing: -.02em;
  line-height: .95;
  font-weight: 900;
}
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px 28px; margin: 25px 0; }
.help-grid h3 { display: flex; align-items: center; gap: 8px; margin: 0 0 7px; font-size: 10px; letter-spacing: .15em; color: #dfe9dd; }
.help-grid h3 span { font-family: var(--display); font-size: 17px; color: var(--orange); }
.help-grid p { margin: 0; font-size: 11px; line-height: 1.65; color: #8fa195; }
.help-grid kbd { margin: 0 1px; }
.help-tip {
  margin: 0 0 22px;
  padding: 10px 13px;
  border-left: 2px solid var(--orange);
  background: rgba(255, 122, 26, .07);
  font-size: 10px;
  line-height: 1.5;
  color: #a5b5a8;
}
.help-tip b { color: var(--orange-2); margin-right: 6px; letter-spacing: .15em; }
.deploy-btn.compact { min-width: 0; width: auto; display: inline-flex; }
.pause-card { width: min(430px, 100%); text-align: center; }
.pause-card .eyebrow { justify-content: center; }
.pause-sub { color: #879a8c; font-size: 11px; line-height: 1.6; margin: 4px 0 22px; }
.pause-controls { display: flex; justify-content: center; gap: 22px; margin-top: 20px; font-size: 8px; letter-spacing: .12em; color: #637369; }

/* ============ HUD ============ */
#hud { z-index: 15; }
#hud.active { pointer-events: none; }
#hud.active button, #hud.active .mobile-controls, #hud.active .joystick { pointer-events: auto; }

.hud-top {
  position: absolute;
  top: max(14px, env(safe-area-inset-top));
  left: max(16px, env(safe-area-inset-left));
  right: max(16px, env(safe-area-inset-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}
.hud-left { display: flex; align-items: center; gap: 8px; }
.mini-brand {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 39px;
  padding: 0 10px;
  margin-right: 4px;
  border: 1px solid var(--line);
  background: rgba(5, 15, 11, .65);
  font-size: 9px;
  letter-spacing: .12em;
  color: #7f9184;
  font-weight: 800;
}
.mini-brand span { font-family: var(--display); font-size: 19px; color: var(--orange); letter-spacing: -.02em; }
.stat-chip {
  display: flex;
  flex-direction: column;
  min-width: 60px;
  height: 39px;
  justify-content: center;
  padding: 0 11px;
  border-left: 2px solid rgba(220, 235, 220, .34);
  background: linear-gradient(90deg, rgba(7, 18, 14, .8), rgba(7, 18, 14, .35));
}
.stat-chip small { font-size: 6px; letter-spacing: .19em; color: #819287; font-weight: 700; }
.stat-chip b { font-family: var(--display); font-size: 21px; line-height: 1; color: #eef3e9; }
.stat-chip.accent { border-left-color: var(--orange); }
.stat-chip.accent b { color: var(--orange-2); }

.zone-banner { width: min(330px, 34vw); text-align: center; padding-top: 2px; }
.zone-top { display: flex; align-items: center; justify-content: center; gap: 9px; font-size: 8px; letter-spacing: .18em; color: #8d9d91; }
.zone-top b { font-family: var(--display); font-size: 19px; color: #eef2e9; letter-spacing: .05em; }
.zone-track { height: 2px; margin: 7px 0 6px; background: rgba(207, 226, 208, .15); overflow: hidden; }
.zone-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, var(--cyan), #b7fff8); box-shadow: 0 0 8px var(--cyan); transform-origin: left; }
.zone-track i.closing { background: linear-gradient(90deg, var(--red), var(--orange-2)); box-shadow: 0 0 9px var(--red); }
.zone-name { display: flex; justify-content: center; align-items: center; gap: 6px; font-size: 7px; letter-spacing: .21em; color: #6e8175; }
.zone-name .dot { width: 4px; height: 4px; background: var(--orange); border-radius: 50%; }
.phase-tag { padding: 2px 4px; background: rgba(255, 122, 26, .13); color: var(--orange-2); letter-spacing: .12em; }

.hud-right { display: flex; align-items: flex-start; gap: 9px; }
.mini-map-wrap {
  position: relative;
  width: clamp(118px, 10.4vw, 154px);
  aspect-ratio: 1;
  padding: 4px;
  border: 1px solid rgba(209, 230, 210, .28);
  background: rgba(4, 12, 9, .78);
  box-shadow: 0 8px 25px rgba(0,0,0,.28);
}
#minimap { width: 100%; height: 100%; display: block; opacity: .94; }
.mini-map-grid { position: absolute; inset: 4px; pointer-events: none; background: linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px); background-size: 25% 25%; }
.mini-map-label {
  position: absolute;
  left: 7px;
  right: 7px;
  bottom: 7px;
  display: flex;
  justify-content: space-between;
  font-size: 5px;
  letter-spacing: .18em;
  color: rgba(229, 240, 227, .62);
  font-weight: 700;
}
.mini-map-label::before { content: ""; position: absolute; left: 0; top: -4px; width: 9px; height: 1px; background: var(--orange); }
.hud-buttons { display: flex; flex-direction: column; gap: 5px; }
.hud-icon { width: 30px; height: 30px; border: 1px solid var(--line); background: rgba(5, 15, 11, .64); display: grid; place-items: center; cursor: pointer; }
.hud-icon svg { width: 13px; height: 13px; fill: #93a598; }
.hud-icon:hover { border-color: var(--orange); }
.hud-icon:hover svg { fill: var(--orange); }
.hud-icon.muted { opacity: .45; }

.kill-feed {
  position: absolute;
  top: max(126px, calc(env(safe-area-inset-top) + 112px));
  right: max(16px, env(safe-area-inset-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  width: 300px;
  pointer-events: none;
}
.kill-item {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 7px 4px 9px;
  border-right: 2px solid rgba(255, 122, 26, .8);
  background: linear-gradient(90deg, transparent, rgba(5, 14, 10, .82));
  font-size: 8px;
  letter-spacing: .07em;
  color: #93a597;
  animation: feedIn .3s ease both;
  white-space: nowrap;
}
.kill-item.me { color: #f2f5ed; }
.kill-item b { color: #dce6da; font-weight: 700; }
.kill-item b.you { color: var(--orange-2); }
.kill-item .weapon { color: #718277; font-size: 7px; }
.kill-item .skull { color: var(--red); font-size: 10px; }
@keyframes feedIn { from { opacity: 0; transform: translateX(12px); } }

.status-toast {
  position: absolute;
  left: 50%;
  top: 22%;
  transform: translate(-50%, -8px);
  padding: 8px 18px;
  border: 1px solid rgba(255, 170, 73, .45);
  background: rgba(7, 17, 13, .82);
  color: #f6e6cf;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .15em;
  text-align: center;
  opacity: 0;
  transition: .25s;
  clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%);
  white-space: nowrap;
}
.status-toast.show { opacity: 1; transform: translate(-50%, 0); }
.status-toast.danger { border-color: rgba(255, 77, 61, .7); color: #ffc2ba; }

.pickup-prompt {
  position: absolute;
  left: 50%;
  bottom: 27%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  background: rgba(4, 13, 9, .82);
  border: 1px solid rgba(215, 233, 214, .22);
  font-size: 9px;
  letter-spacing: .08em;
  color: #dbe6d9;
  opacity: 0;
  visibility: hidden;
  transition: .15s;
}
.pickup-prompt.show { opacity: 1; visibility: visible; }
.pickup-prompt kbd { background: var(--orange); color: #1b0d03; border: 0; font-size: 9px; }
.pickup-prompt span b { color: var(--orange-2); }

.hud-bottom {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  right: max(18px, env(safe-area-inset-right));
  bottom: max(18px, env(safe-area-inset-bottom));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}
.vitals { width: clamp(200px, 18vw, 270px); }
.vital-row { display: flex; align-items: center; gap: 7px; margin-top: 5px; }
.vital-row.small { width: 77%; }
.vital-icon { width: 17px; height: 17px; display: grid; place-items: center; font-size: 12px; font-weight: 900; color: #09120d; background: var(--green); }
.vital-icon.armor { background: #6ac8e8; font-size: 8px; }
.bar {
  position: relative;
  flex: 1;
  height: 17px;
  background: rgba(4, 13, 9, .8);
  border: 1px solid rgba(212, 232, 212, .2);
  overflow: hidden;
  clip-path: polygon(0 0, 100% 0, calc(100% - 5px) 100%, 0 100%);
}
.bar i {
  display: block;
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #5ec44e, #b2f67c);
  box-shadow: 0 0 12px rgba(135, 230, 107, .25);
  transition: width .14s;
}
.bar.armor-bar { height: 11px; }
.armor-bar i { background: linear-gradient(90deg, #3199c8, #78e6f5); }
.bar em {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 8px;
  font-style: normal;
  font-family: var(--display);
  font-size: 12px;
  letter-spacing: .06em;
  color: rgba(6, 15, 9, .8);
  font-weight: 900;
}
.bar.armor-bar em { font-size: 8px; color: rgba(2, 20, 28, .8); }
.consumables { display: flex; gap: 6px; margin-top: 7px; }
.consumable {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px;
  border: 1px solid rgba(212, 232, 212, .16);
  background: rgba(4, 13, 9, .6);
}
.consumable b { color: var(--orange-2); font-size: 11px; }
.consumable small { font-size: 8px; color: #b3c1b4; }

.weapon-panel {
  position: relative;
  width: clamp(250px, 24vw, 330px);
  min-height: 72px;
  padding: 8px 11px 9px;
  border: 1px solid rgba(211, 231, 211, .17);
  background: linear-gradient(135deg, rgba(8, 21, 16, .86), rgba(5, 13, 10, .62));
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
}
.weapon-panel::after { content: ""; position: absolute; left: 0; top: 0; width: 2px; height: 32px; background: var(--orange); }
.weapon-slots { position: absolute; right: 8px; top: 7px; display: flex; gap: 3px; }
.slot { display: grid; place-items: center; width: 15px; height: 15px; border: 1px solid rgba(213, 232, 214, .2); color: #64766b; font-size: 7px; font-weight: 700; }
.slot.active { border-color: var(--orange); background: var(--orange); color: #1b0d03; }
.weapon-main { display: flex; gap: 9px; align-items: center; }
.weapon-icon { width: 66px; height: 34px; display: grid; place-items: center; color: #cfdbcf; opacity: .9; }
.weapon-icon svg { width: 100%; height: auto; filter: drop-shadow(0 2px 2px rgba(0,0,0,.5)); }
.weapon-info { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.weapon-info > span { font-size: 6px; letter-spacing: .19em; color: #7a8c7f; font-weight: 700; }
.weapon-info > b { font-size: 11px; letter-spacing: .1em; color: #e8efe3; white-space: nowrap; }
.ammo-line { display: flex; align-items: baseline; gap: 3px; line-height: 1; margin-top: 1px; }
.ammo-line strong { font-family: var(--display); font-size: 23px; letter-spacing: .03em; color: #fff; }
.ammo-line span { color: #627368; font-size: 10px; }
.ammo-line small { font-size: 10px; color: #84978a; }
.reload-wrap { height: 2px; margin-top: 7px; background: rgba(212, 232, 212, .12); overflow: hidden; }
.reload-wrap i { display: block; height: 100%; width: 0; background: var(--orange); box-shadow: 0 0 7px var(--orange); }
.weapon-hint { position: absolute; right: 8px; bottom: 5px; font-size: 6px; letter-spacing: .15em; color: #687b6e; }

.action-cluster { display: flex; gap: 14px; padding-bottom: 3px; }
.action-hint { display: flex; flex-direction: column; align-items: center; gap: 3px; color: #6f8175; font-size: 6px; letter-spacing: .11em; }
.action-hint kbd { margin: 0; width: 24px; height: 24px; background: rgba(4, 13, 9, .7); }

.crosshair {
  position: fixed;
  left: 50%;
  top: 50%;
  z-index: 18;
  width: 34px;
  height: 34px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  opacity: 0;
  transition: opacity .15s;
}
#hud.active .crosshair { opacity: 1; }
.crosshair i { position: absolute; background: rgba(247, 251, 240, .85); box-shadow: 0 0 3px rgba(0,0,0,.8); }
.crosshair i:nth-child(1) { width: 2px; height: 7px; left: 16px; top: 1px; }
.crosshair i:nth-child(2) { width: 2px; height: 7px; left: 16px; bottom: 1px; }
.crosshair i:nth-child(3) { width: 7px; height: 2px; left: 1px; top: 16px; }
.crosshair i:nth-child(4) { width: 7px; height: 2px; right: 1px; top: 16px; }
.crosshair span { position: absolute; width: 2px; height: 2px; left: 16px; top: 16px; border-radius: 50%; background: var(--orange); }
.crosshair.hot i { background: var(--orange-2); }

.hitmarker {
  position: fixed;
  left: 50%;
  top: 50%;
  z-index: 19;
  width: 26px;
  height: 26px;
  transform: translate(-50%, -50%) rotate(45deg) scale(1.4);
  opacity: 0;
  pointer-events: none;
  transition: opacity .1s, transform .1s;
}
.hitmarker::before, .hitmarker::after { content: ""; position: absolute; background: #fff; box-shadow: 0 0 3px rgba(0,0,0,.8); }
.hitmarker::before { left: 12px; top: 0; width: 2px; height: 26px; }
.hitmarker::after { top: 12px; left: 0; height: 2px; width: 26px; }
.hitmarker.show { opacity: 1; transform: translate(-50%, -50%) rotate(45deg) scale(1); }
.hitmarker.kill::before, .hitmarker.kill::after { background: var(--red); }

/* ============ MOBILE ============ */
.mobile-controls { display: none; }
.joystick {
  position: absolute;
  width: 126px;
  height: 126px;
  border-radius: 50%;
  border: 1px solid rgba(214, 235, 214, .2);
  background: radial-gradient(circle, rgba(7, 18, 13, .22), rgba(7, 18, 13, .5));
  bottom: max(28px, env(safe-area-inset-bottom));
  touch-action: none;
  backdrop-filter: blur(2px);
}
.move-stick { left: max(22px, env(safe-area-inset-left)); }
.aim-stick { right: max(22px, env(safe-area-inset-right)); }
.joystick > span { position: absolute; bottom: 9px; left: 50%; transform: translateX(-50%); font-size: 6px; letter-spacing: .2em; color: rgba(205, 222, 205, .45); }
.stick-ring { position: absolute; inset: 15px; border-radius: 50%; border: 1px dashed rgba(211, 231, 211, .12); }
.stick-ring i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 48px;
  height: 48px;
  margin: -24px 0 0 -24px;
  border-radius: 50%;
  border: 1px solid rgba(255, 155, 68, .48);
  background: radial-gradient(circle at 35% 30%, rgba(255, 166, 79, .3), rgba(255, 112, 21, .09));
  box-shadow: 0 0 22px rgba(255, 110, 20, .15);
}
.mobile-actions {
  position: absolute;
  right: max(24px, env(safe-area-inset-right));
  bottom: max(175px, calc(env(safe-area-inset-bottom) + 160px));
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: flex-end;
  gap: 8px;
  width: 180px;
}
.mob-btn {
  border: 1px solid rgba(212, 232, 212, .28);
  background: rgba(5, 15, 11, .66);
  color: #d7e2d5;
  font-family: var(--font);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .08em;
  display: grid;
  place-items: center;
  border-radius: 50%;
  touch-action: none;
  backdrop-filter: blur(3px);
}
.mob-btn.small { width: 38px; height: 38px; }
.mob-btn.fire {
  width: 72px;
  height: 72px;
  border-color: rgba(255, 131, 34, .72);
  background: radial-gradient(circle at 35% 30%, rgba(255, 147, 52, .44), rgba(204, 64, 5, .55));
  color: #fff3e5;
  font-size: 10px;
  letter-spacing: .13em;
  box-shadow: 0 0 26px rgba(255, 91, 10, .24);
}
.mob-btn:active { background: rgba(255, 122, 26, .45); }
.mob-btn.fire:active { transform: scale(.94); }

/* ============ RESULT ============ */
.result-screen {
  z-index: 70;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at center, rgba(10, 25, 19, .4), rgba(2, 8, 6, .92) 72%);
  backdrop-filter: blur(6px);
}
.result-screen.active { display: grid; }
.result-glow {
  position: absolute;
  width: min(800px, 100vw);
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 122, 26, .16), transparent 60%);
  pointer-events: none;
}
.result-screen.lost .result-glow { background: radial-gradient(circle, rgba(255, 45, 35, .12), transparent 60%); }
.result-card {
  position: relative;
  width: min(600px, calc(100% - 40px));
  padding: 30px 38px 34px;
  border: 1px solid rgba(216, 235, 214, .18);
  background: linear-gradient(155deg, rgba(15, 34, 25, .96), rgba(5, 13, 10, .97));
  text-align: center;
  clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 20px 100%, 0 calc(100% - 20px));
  animation: resultIn .5s cubic-bezier(.2, .8, .2, 1) both;
}
@keyframes resultIn { from { opacity: 0; transform: translateY(20px) scale(.97); } }
.result-kicker { font-size: 8px; letter-spacing: .35em; color: #8c9e91; font-weight: 700; }
.result-card h2 {
  margin: 7px 0 4px;
  font-family: var(--display);
  font-size: clamp(60px, 10vw, 96px);
  line-height: .85;
  letter-spacing: -.02em;
  color: var(--orange);
  text-shadow: 0 0 35px rgba(255, 110, 20, .28);
}
.result-screen.lost .result-card h2 { color: #c3cac1; text-shadow: none; }
.result-card > p { margin: 6px 0 0; font-size: 11px; color: #91a396; letter-spacing: .04em; }
.result-rank { position: absolute; right: 32px; top: 25px; font-family: var(--display); font-size: 38px; color: rgba(218, 232, 218, .14); }
.result-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; margin: 26px 0 24px; background: rgba(218, 232, 218, .1); }
.result-stats div { background: #0b1b14; padding: 12px 6px; display: flex; flex-direction: column; gap: 4px; }
.result-stats span { font-size: 6px; letter-spacing: .16em; color: #72857a; font-weight: 700; }
.result-stats b { font-family: var(--display); font-size: 25px; line-height: 1; color: #eef3e9; }
.result-actions { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.result-actions .deploy-btn { min-width: 240px; }
.result-actions .ghost-btn { min-height: 66px; }

.rotate-hint {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: none;
  place-items: center;
  padding: 30px;
  background: #07110e;
  color: #c6d4c6;
  font-size: 11px;
  letter-spacing: .2em;
  text-align: center;
  text-transform: uppercase;
}

@media (max-width: 1050px) {
  .hero { grid-template-columns: minmax(0, 1fr) minmax(300px, .72fr); gap: 28px; }
  .hero-panel { max-width: 390px; justify-self: end; }
  .quick-stats { gap: 24px; }
  .controls-strip span:nth-child(n+5) { display: none; }
}
@media (max-width: 820px) {
  #menu { padding: 16px 20px 14px; overflow-y: auto; }
  .hero { grid-template-columns: 1fr; gap: 22px; align-items: start; padding: 4vh 0 2vh; }
  .hero-panel { display: none; }
  .hero-copy { max-width: none; }
  h1 { font-size: clamp(78px, 21vw, 148px); }
  .tagline { font-size: 20px; }
  .intro { margin-bottom: 20px; }
  .quick-stats { margin-top: 22px; }
  .menu-bottom { flex-direction: column; align-items: flex-start; gap: 9px; }
