(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = Object.fromEntries(['menu','help','hud','pause','result','deployBtn','helpBtn','helpClose','helpDeploy','resumeBtn','quitBtn','againBtn','menuBtn','pauseBtn','menuSound','gameSound','menuFullscreen','aliveCount','killCount','zoneState','zoneTimer','zoneProgress','phaseTag','healthBar','healthText','armorBar','armorText','medkitCount','glooCount','weaponClass','weaponName','ammoMag','ammoReserve','reloadBar','weaponHint','slot1','slot2','killFeed','statusToast','pickupPrompt','damageFlash','hitmarker','minimap','crosshair','mobileFire','mobileReload','mobileHeal','mobilePickup','mobileGloo','moveStick','aimStick','resultKicker','resultTitle','resultSub','resultKills','resultDamage','resultTime','resultPlace','resultRank'].map(k => [k,$(k)]));
  const W=2600,H=1900,TAU=Math.PI*2;
  let vw=innerWidth,vh=innerHeight,dpr=1,last=0,raf=0,started=false,paused=false,sound=true,audio=null;
  const keys=new Set(), pointer={x:vw/2,y:vh/2,down:false};
  let player,bots=[],bullets=[],loot=[],walls=[],buildings=[],trees=[],camera={x:0,y:0},safe={x:W/2,y:H/2,r:1120,start:1120,target:1120},gameTime=0,zonePhase=1,zoneClock=28,kills=0,damage=0,medkits=1,gloos=2,toastTimer=0,shotTimer=0,stepTimer=0,matchEnd=false;
  const weapons=[{name:'P92 PISTOL',type:'SIDEARM',magSize:15,rate:.24,damage:24,range:470,reload:1.15,speed:690},{name:'SCAR-L RIFLE',type:'ASSAULT RIFLE',magSize:30,rate:.105,damage:17,range:710,reload:1.55,speed:860}];
  let weaponIndex=0,weapon=weapons[0];
  const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),angle=(a,b)=>Math.atan2(b.y-a.y,b.x-a.x);
  function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);canvas.style.width=vw+'px';canvas.style.height=vh+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  function soundFX(freq=180,duration=.08,type='square',volume=.025){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch(_){}}
  function setSound(){sound=!sound;document.querySelectorAll('#menuSound,#gameSound').forEach(b=>b.classList.toggle('muted',!sound));if(sound)soundFX(440,.07,'sine')}
  function toast(text,danger=false){ui.statusToast.textContent=text;ui.statusToast.classList.toggle('danger',danger);ui.statusToast.classList.add('show');toastTimer=2.2}
  function addFeed(a,b,me=false){const item=document.createElement('div');item.className='kill-item'+(me?' me':'');item.innerHTML=`<b class="${me?'you':''}">${a}</b><span class="skull">✕</span><b>${b}</b><span class="weapon">${me?'SCAR-L':'ISLAND'}</span>`;ui.killFeed.prepend(item);while(ui.killFeed.children.length>4)ui.killFeed.lastChild.remove();setTimeout(()=>item.remove(),6500)}
  function showScreen(el){[ui.menu,ui.hud,ui.result].forEach(x=>x.classList.toggle('active',x===el))}
  function randomPoint(margin=90){return{x:rand(margin,W-margin),y:rand(margin,H-margin)}}
  function makeWorld(){buildings=[];trees=[];loot=[];walls=[];
    // settlements connected by broad, dusty roads
    const centers=[[540,470],[1260,420],[2020,570],[720,1280],[1630,1260],[2180,1480],[1280,920]];
    centers.forEach((c,ci)=>{for(let i=0;i<5;i++){let x=c[0]+rand(-175,175),y=c[1]+rand(-130,130),w=rand(72,145),h=rand(58,112);buildings.push({x,y,w,h,tone:Math.floor(rand(0,4)),roof:Math.random()>.5,door:rand(0,1)});if(Math.random()<.8)loot.push(makeLoot(x+rand(-w/3,w/3),y+rand(-h/3,h/3)))};for(let i=0;i<16;i++){const p={x:c[0]+rand(-260,260),y:c[1]+rand(-200,200),r:rand(17,30),tone:Math.random()};if(!buildings.some(b=>p.x>b.x-35&&p.x<b.x+b.w+35&&p.y>b.y-35&&p.y<b.y+b.h+35))trees.push(p)}});
    for(let i=0;i<125;i++){let p=randomPoint(70);if(!buildings.some(b=>p.x>b.x-32&&p.x<b.x+b.w+32&&p.y>b.y-32&&p.y<b.y+b.h+32))trees.push({...p,r:rand(14,29),tone:Math.random()})}
    for(let i=0;i<24;i++){let p=randomPoint(140);loot.push(makeLoot(p.x,p.y))}
  }
  function makeLoot(x,y){const kind=Math.random()<.26?'medkit':Math.random()<.36?'ammo':Math.random()<.65?'rifle':'armor';return{x,y,kind,phase:rand(0,TAU),taken:false}}
  function reset(){makeWorld();player={x:rand(700,1900),y:rand(500,1400),r:15,hp:100,armor:0,speed:205,angle:0,mag:15,reserve:60,rifle:false,rifleMag:30,rifleReserve:90,reload:0,slide:0,fireCd:0,flash:0,moveX:0,moveY:0};bots=[];for(let i=0;i<23;i++){let p=randomPoint(180);while(dist(p,player)<350)p=randomPoint(180);bots.push({x:p.x,y:p.y,r:14,hp:100,angle:0,speed:rand(65,105),fireCd:rand(.4,2),wander:rand(0,TAU),wanderTime:rand(1,4),color:['#c66a48','#748b63','#a58b5e','#6c8490','#b56d52'][i%5],alive:true,armor:Math.random()<.42?rand(10,35):0})}bullets=[];kills=0;damage=0;medkits=1;gloos=2;gameTime=0;zonePhase=1;zoneClock=28;safe={x:W/2,y:H/2,r:1120,start:1120,target:1120};weaponIndex=0;weapon=weapons[0];matchEnd=false;paused=false;ui.killFeed.innerHTML='';ui.pause.classList.remove('open');updateUI();camera.x=player.x;camera.y=player.y}
  function deploy(){reset();started=true;showScreen(ui.hud);ui.help.classList.remove('open');toast('DROP ZONE: ISLA CALIENTE');soundFX(130,.35,'sawtooth',.04);last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
  function openPause(){if(!started||matchEnd)return;paused=true;ui.pause.classList.add('open')}
  function resume(){paused=false;ui.pause.classList.remove('open');last=performance.now()}
  function quit(){started=false;paused=false;ui.pause.classList.remove('open');showScreen(ui.menu)}
  ui.deployBtn.onclick=deploy;ui.helpDeploy.onclick=deploy;ui.helpBtn.onclick=()=>ui.help.classList.add('open');ui.helpClose.onclick=()=>ui.help.classList.remove('open');ui.pauseBtn.onclick=openPause;ui.resumeBtn.onclick=resume;ui.quitBtn.onclick=quit;ui.againBtn.onclick=deploy;ui.menuBtn.onclick=quit;ui.menuSound.onclick=setSound;ui.gameSound.onclick=setSound;
  ui.menuFullscreen.onclick=()=>{if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()};
  addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.repeat)return;if(e.key==='Escape'){if(ui.help.classList.contains('open'))ui.help.classList.remove('open');else if(paused)resume();else openPause()}if(!started||paused)return;const k=e.key.toLowerCase();if(k==='r')reload();if(k==='e')pickup();if(k==='h')heal();if(k==='g')gloo();if(k==='1')switchWeapon(0);if(k==='2')switchWeapon(1);if(k===' '){player.slide=.65;soundFX(100,.12,'sawtooth')}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY});canvas.addEventListener('pointerdown',e=>{if(e.button===0){pointer.down=true;canvas.setPointerCapture?.(e.pointerId)}});addEventListener('pointerup',e=>{if(e.button===0)pointer.down=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
  addEventListener('wheel',e=>{if(started&&!paused)switchWeapon(1-weaponIndex)},{passive:true});
  function bindAction(id,fn){$(id).addEventListener('pointerdown',e=>{e.preventDefault();fn()})}bindAction('mobileReload',reload);bindAction('mobileHeal',heal);bindAction('mobilePickup',pickup);bindAction('mobileGloo',gloo);$('mobileFire').addEventListener('pointerdown',e=>{e.preventDefault();pointer.down=true});$('mobileFire').addEventListener('pointerup',()=>pointer.down=false);$('mobileFire').addEventListener('pointercancel',()=>pointer.down=false);
  const sticks={move:{x:0,y:0,id:null},aim:{x:0,y:0,id:null}};
  function bindStick(el,key){el.addEventListener('pointerdown',e=>{e.preventDefault();sticks[key].id=e.pointerId;el.setPointerCapture(e.pointerId);stickMove(e,el,key)});el.addEventListener('pointermove',e=>{if(sticks[key].id===e.pointerId)stickMove(e,el,key)});const end=e=>{if(sticks[key].id===e.pointerId){sticks[key].id=null;sticks[key].x=0;sticks[key].y=0;el.querySelector('.stick-ring i').style.transform='translate(0,0)';if(key==='aim')pointer.down=false}};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)}
  function stickMove(e,el,key){const r=el.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=r.width*.34,s=len>max?max/len:1;sticks[key].x=dx/max;sticks[key].y=dy/max;el.querySelector('.stick-ring i').style.transform=`translate(${dx*s}px,${dy*s}px)`;if(key==='aim'){player.angle=Math.atan2(dy,dx);pointer.down=Math.hypot(dx,dy)>9}}
  bindStick(ui.moveStick,'move');bindStick(ui.aimStick,'aim');
  function switchWeapon(i){if(!player)return;if(i===1&&!player.rifle){toast('FIND AN ASSAULT RIFLE');return}weaponIndex=i;weapon=weapons[i];updateUI()}
  function ammo(){return weaponIndex?player.rifleMag:player.mag}function reserve(){return weaponIndex?player.rifleReserve:player.reserve}
  function setAmmo(m,r){if(weaponIndex){player.rifleMag=m;player.rifleReserve=r}else{player.mag=m;player.reserve=r}}
  function reload(){if(!started||paused||player.reload||ammo()===weapon.magSize||reserve()<=0)return;player.reload=weapon.reload;toast('RELOADING');soundFX(280,.06,'triangle')}
  function heal(){if(!started||paused)return;if(medkits<1){toast('NO MEDKITS');return}if(player.hp>=100){toast('HEALTH ALREADY FULL');return}medkits--;player.hp=Math.min(100,player.hp+48);soundFX(520,.16,'sine');toast('MEDKIT USED · +48 HP');updateUI()}
  function pickup(){if(!started||paused)return;const item=nearestLoot(64);if(!item){toast('NO LOOT IN RANGE');return}takeLoot(item)}
  function nearestLoot(max=75){let found=null,d=max;loot.forEach(l=>{if(l.taken)return;const n=dist(player,l);if(n<d){found=l;d=n}});return found}
  function takeLoot(l){l.taken=true;if(l.kind==='medkit'){medkits++;toast('MEDKIT ACQUIRED')}else if(l.kind==='ammo'){player.reserve+=24;player.rifleReserve+=30;toast('AMMO +24')}else if(l.kind==='rifle'){player.rifle=true;player.rifleMag=Math.max(player.rifleMag,24);player.rifleReserve+=45;switchWeapon(1);toast('SCAR-L ACQUIRED')}else{player.armor=Math.min(100,player.armor+35);toast('ARMOR +35')}soundFX(620,.08,'sine');updateUI()}
  function gloo(){if(!started||paused)return;if(gloos<=0){toast('NO GLOO WALLS');return}gloos--;const x=player.x+Math.cos(player.angle)*54,y=player.y+Math.sin(player.angle)*54;walls.push({x,y,a:player.angle+Math.PI/2,life:18});soundFX(110,.2,'triangle');toast('GLOO WALL DEPLOYED')}
  function shoot(shooter,isPlayer){const w=isPlayer?weapon:{damage:rand(7,12),range:440,speed:590};if(isPlayer){if(player.reload)return;if(ammo()<=0){if(reserve()>0)reload();else toast('OUT OF AMMO');return}setAmmo(ammo()-1,reserve());player.fireCd=weapon.rate;player.flash=.08;soundFX(weaponIndex?125:190,.06,'square',.018)}const a=shooter.angle+(isPlayer?rand(-.035,.035):rand(-.16,.16));bullets.push({x:shooter.x+Math.cos(a)*18,y:shooter.y+Math.sin(a)*18,vx:Math.cos(a)*w.speed,vy:Math.sin(a)*w.speed,life:w.range/w.speed,damage:w.damage,owner:isPlayer?'player':'bot',source:shooter});if(isPlayer)updateUI()}

