  function hurt(target,amount,byPlayer=false){if(target===player){const absorbed=Math.min(player.armor,amount*.55);player.armor-=absorbed;player.hp-=amount-absorbed;ui.damageFlash.classList.add('hit');setTimeout(()=>ui.damageFlash.classList.remove('hit'),100);soundFX(72,.07,'sawtooth',.035);if(player.hp<=0)finish(false);updateUI();return}let hit=amount;if(target.armor){const soak=Math.min(target.armor,amount*.55);target.armor-=soak;hit-=soak}target.hp-=hit;if(byPlayer){damage+=Math.round(hit);ui.hitmarker.classList.add('show');setTimeout(()=>ui.hitmarker.classList.remove('show'),100)}if(target.hp<=0){target.alive=false;const idx=bots.indexOf(target);if(idx>=0)bots.splice(idx,1);loot.push(makeLoot(target.x,target.y));addFeed(byPlayer?'YOU':`OP-${Math.ceil(Math.random()*23)}`,byPlayer?'OPERATOR':`OP-${Math.ceil(Math.random()*23)}`,byPlayer);if(byPlayer){kills++;soundFX(580,.14,'sine')}else soundFX(210,.12,'triangle');updateUI();if(bots.length===0)finish(true)}}
  function finish(win){if(matchEnd)return;matchEnd=true;started=false;ui.result.classList.toggle('lost',!win);ui.resultKicker.textContent=win?'LAST OPERATOR STANDING':'MATCH COMPLETE';ui.resultTitle.textContent=win?'BOOYAH!':'ELIMINATED';ui.resultSub.textContent=win?'You are the last operator standing.':'The island claimed another operator. Redeploy and try again.';ui.resultKills.textContent=kills;ui.resultDamage.textContent=damage;ui.resultTime.textContent=`${Math.floor(gameTime/60)}:${String(Math.floor(gameTime%60)).padStart(2,'0')}`;ui.resultPlace.textContent=win?'1 / 24':`${Math.min(24,bots.length+1)} / 24`;ui.resultRank.textContent=win?'#1':`#${Math.min(24,bots.length+1)}`;showScreen(ui.result);soundFX(win?660:100,.45,win?'sine':'sawtooth',.045)}
