    if(player.reload>0){player.reload-=dt;ui.reloadBar.style.width=`${100*(1-player.reload/weapon.reload)}%`;if(player.reload<=0){const need=weapon.magSize-ammo(),load=Math.min(need,reserve());setAmmo(ammo()+load,reserve()-load);ui.reloadBar.style.width='0%';soundFX(320,.05,'triangle');updateUI()}}
    const mx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+sticks.move.x,my=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+sticks.move.y,mLen=Math.hypot(mx,my);let speed=player.speed*(keys.has('shift')?1.42:1)*(player.slide>0?1.8:1);player.x=clamp(player.x+(mLen?mx/mLen*speed*dt:0),24,W-24);player.y=clamp(player.y+(mLen?my/mLen*speed*dt:0),24,H-24);if(mLen&&stepTimer<=0){stepTimer=.34;soundFX(85,.025,'triangle',.005)}stepTimer-=dt;
    const worldMouse={x:pointer.x-vw/2+camera.x,y:pointer.y-vh/2+camera.y};if(sticks.aim.id===null)player.angle=angle(player,worldMouse);camera.x+=(player.x-camera.x)*Math.min(1,dt*5);camera.y+=(player.y-camera.y)*Math.min(1,dt*5);
