    // AI operators patrol, seek nearby threats, and fight each other.
    for(let i=0;i<bots.length;i++){const b=bots[i];b.fireCd-=dt;b.wanderTime-=dt;let target=player,td=dist(b,player);for(let j=0;j<bots.length;j++){const other=bots[j];if(other!==b){const d=dist(b,other);if(d<td&&d<430){target=other;td=d}}}if(td>470&&target===player)target=null;if(target){b.angle=angle(b,target);if(td>200){b.x+=Math.cos(b.angle)*b.speed*dt;b.y+=Math.sin(b.angle)*b.speed*dt}else if(Math.random()<dt*.55){b.wander=b.angle+(Math.random()-.5)*2.5;b.x+=Math.cos(b.wander)*b.speed*.4*dt;b.y+=Math.sin(b.wander)*b.speed*.4*dt}if(td<380&&b.fireCd<=0){const a=Math.atan2(target.y-b.y,target.x-b.x);b.angle=a;const fake={...b,angle:a};shoot(fake,false);b.fireCd=rand(.8,1.7)}}else{if(b.wanderTime<=0){b.wander=rand(0,TAU);b.wanderTime=rand(1.5,4)}b.x+=Math.cos(b.wander)*b.speed*.35*dt;b.y+=Math.sin(b.wander)*b.speed*.35*dt}b.x=clamp(b.x,30,W-30);b.y=clamp(b.y,30,H-30);if(Math.hypot(b.x-safe.x,b.y-safe.y)>safe.r){hurt(b,dt*7,false)}}
    // Projectiles: collisions, cover, and lifetime.
    for(let i=bullets.length-1;i>=0;i--){const q=bullets[i];q.x+=q.vx*dt;q.y+=q.vy*dt;q.life-=dt;let removed=q.life<=0||q.x<0||q.y<0||q.x>W||q.y>H;for(const wall of walls){if(!removed&&Math.hypot(q.x-wall.x,q.y-wall.y)<25)removed=true}if(!removed&&buildings.some(b=>q.x>b.x&&q.x<b.x+b.w&&q.y>b.y&&q.y<b.y+b.h))removed=true;if(!removed&&q.owner==='player'){for(const b of bots){if(Math.hypot(q.x-b.x,q.y-b.y)<b.r+4){hurt(b,q.damage,true);removed=true;break}}}else if(!removed&&q.owner==='bot'&&Math.hypot(q.x-player.x,q.y-player.y)<player.r+4){hurt(player,q.damage);removed=true}else if(!removed&&q.owner==='bot'){for(const b of bots){if(b!==q.source&&Math.hypot(q.x-b.x,q.y-b.y)<b.r+4){hurt(b,q.damage,false);removed=true;break}}}if(removed)bullets.splice(i,1)}
