    if(zonePhase%2===0){const t=1-clamp(zoneClock/24,0,1);safe.r=safe.start+(safe.target-safe.start)*t}const pd=Math.hypot(player.x-safe.x,player.y-safe.y);const storm=pd>safe.r;if(storm){hurt(player,dt*7);ui.damageFlash.classList.add('storm')}else ui.damageFlash.classList.remove('storm');
    // loot prompt and ambient bot eliminations prevent a stalled match
    const near=nearestLoot(80);ui.pickupPrompt.classList.toggle('show',!!near);if(near)ui.pickupPrompt.querySelector('span').innerHTML=`PICK UP <b>${near.kind.toUpperCase()}</b>`;
    if(gameTime>85&&bots.length>1&&Math.random()<dt*.13){const a=Math.floor(Math.random()*bots.length),b=Math.floor(Math.random()*bots.length);if(a!==b){const victim=bots[b],killer=bots[a];victim.hp-=rand(25,70);if(victim.hp<=0){victim.alive=false;bots.splice(b,1);addFeed(`OP-${a+1}`,`OP-${b+1}`);loot.push(makeLoot(victim.x,victim.y));updateUI()}}}
    updateUI();drawMini();
  }
  function updateUI(){if(!player)return;ui.aliveCount.textContent=bots.length+1;ui.killCount.textContent=kills;ui.healthBar.style.width=`${clamp(player.hp,0,100)}%`;ui.healthText.textContent=Math.max(0,Math.ceil(player.hp));ui.armorBar.style.width=`${clamp(player.armor,0,100)}%`;ui.armorText.textContent=Math.ceil(player.armor);ui.medkitCount.textContent=medkits;ui.glooCount.textContent=gloos;ui.weaponClass.textContent=weapon.type;ui.weaponName.textContent=weapon.name;ui.ammoMag.textContent=ammo();ui.ammoReserve.textContent=reserve();ui.slot1.classList.toggle('active',weaponIndex===0);ui.slot2.classList.toggle('active',weaponIndex===1);ui.zoneTimer.textContent=`${Math.floor(zoneClock/60)}:${String(Math.floor(zoneClock%60)).padStart(2,'0')}`;ui.zoneProgress.style.transform=`scaleX(${clamp(zoneClock/(zonePhase%2?28:24),0,1)})`;ui.zoneProgress.classList.toggle('closing',zonePhase%2===0);ui.weaponHint.textContent=player.reload?'RELOADING':(pointer.down?'FIRING':'AUTO')}
  function drawMini(){const c=ui.minimap, m=c.getContext('2d'),s=c.width/W;c.width=220;c.height=220;m.fillStyle='#1b382d';m.fillRect(0,0,220,220);m.strokeStyle='rgba(202,177,119,.35)';m.lineWidth=7;m.beginPath();m.moveTo(0,82);m.lineTo(220,130);m.moveTo(70,0);m.lineTo(136,220);m.stroke();m.fillStyle='#5e6143';for(const b of buildings)m.fillRect(b.x*s,b.y*s,Math.max(1,b.w*s),Math.max(1,b.h*s));m.strokeStyle='#68d8dc';m.lineWidth=2;m.beginPath();m.arc(safe.x*s,safe.y*s,safe.r*s,0,TAU);m.stroke();m.fillStyle='#ff8050';bots.forEach(b=>{m.beginPath();m.arc(b.x*s,b.y*s,2.2,0,TAU);m.fill()});m.fillStyle='#fff';m.beginPath();m.arc(player.x*s,player.y*s,3,0,TAU);m.fill();m.strokeStyle='#fff';m.beginPath();m.moveTo(player.x*s,player.y*s);m.lineTo((player.x+Math.cos(player.angle)*22)*s,(player.y+Math.sin(player.angle)*22)*s);m.stroke()}

